from __future__ import annotations

import json
import re
from typing import Any


class JsonContractError(Exception):
    pass


def extract_first_json_object(text: str) -> dict[str, Any]:
    # tolerant extractor: find first {...} parseable block
    candidates = re.finditer(r"\{", text)
    for c in candidates:
        start = c.start()
        for end in range(len(text), start + 1, -1):
            chunk = text[start:end].strip()
            if not chunk.endswith("}"):
                continue
            try:
                obj = json.loads(chunk)
                if isinstance(obj, dict):
                    return obj
            except Exception:
                pass
    raise JsonContractError("No valid JSON object found")


def validate_required_keys(obj: dict[str, Any], required: list[str]) -> None:
    missing = [k for k in required if k not in obj]
    if missing:
        raise JsonContractError(f"Missing required keys: {missing}")


def parse_and_validate(text: str, required: list[str]) -> dict[str, Any]:
    try:
        obj = json.loads(text)
        if not isinstance(obj, dict):
            raise JsonContractError("Top-level JSON must be an object")
    except Exception:
        obj = extract_first_json_object(text)

    validate_required_keys(obj, required)
    return obj

