    max_attempts: int = 5
    base_delay_sec: float = 1.0
    max_delay_sec: float = 60.0
    budget_per_job: int = 10

    def backoff_with_jitter(self, attempt: int) -> float:
        exp = min(self.max_delay_sec, self.base_delay_sec * (2 ** max(0, attempt - 1)))
        return random.uniform(0, exp)


@dataclass
class CircuitBreaker:
    threshold: int = 5
    recovery_sec: float = 30.0
    _failures: int = 0
    _opened_at: float | None = None

    def record_success(self) -> None:
        self._failures = 0
        self._opened_at = None

    def record_failure(self) -> None:
        self._failures += 1
        if self._failures >= self.threshold and self._opened_at is None:
            self._opened_at = time.time()

    def is_open(self) -> bool:
        if self._opened_at is None:
            return False
        if time.time() - self._opened_at >= self.recovery_sec:
            self._failures = 0
            self._opened_at = None
            return False
        return True


