@dataclass
class JobMessage:
    job_id: str
    payload: dict[str, Any]
    attempts: int = 0


@dataclass
class InMemoryQueue:
    pending: deque[JobMessage] = field(default_factory=deque)
    dlq: deque[JobMessage] = field(default_factory=deque)

    def push(self, msg: JobMessage) -> None:
        self.pending.append(msg)

    def pop(self) -> JobMessage | None:
        if not self.pending:
            return None
        return self.pending.popleft()

    def retry_or_dlq(self, msg: JobMessage, max_attempts: int) -> str:
        msg.attempts += 1
        if msg.attempts >= max_attempts:
            self.dlq.append(msg)
            return "dlq"
        self.pending.append(msg)
        return "retry"

