function runHappyPath() {
  const out = analyzeDecision({
    options: [
      { id: 'a', name: 'Build', metrics: { impact: 80, cost: 60, timeToValue: 50, risk: 40 }, notes: ['control'] },
      { id: 'b', name: 'Buy', metrics: { impact: 65, cost: 30, timeToValue: 25, risk: 55 }, notes: ['speed'] },
    ],
    criteria: [
      { id: 'impact', weight: 0.45, direction: 'higher_better' },
      { id: 'cost', weight: 0.25, direction: 'lower_better' },
      { id: 'timeToValue', weight: 0.2, direction: 'lower_better' },
      { id: 'risk', weight: 0.1, direction: 'lower_better' },
    ],
  });

  assert(Array.isArray(out.ranked) && out.ranked.length === 2, 'happy: ranked options invalid');
  assert(Array.isArray(out.riskMatrix) && out.riskMatrix.length === 2, 'happy: risk matrix invalid');
  assert(Array.isArray(out.actionPlanTop3) && out.actionPlanTop3.length === 3, 'happy: action plan invalid');
}

function runEdgeCases() {
  const longText = 'x'.repeat(5000);
  const outLong = analyzeDecision({
    options: [
      { id: 'a', name: longText, metrics: { impact: 60, cost: 40, timeToValue: 40, risk: 40 }, notes: [longText] },
      { id: 'b', name: 'B', metrics: { impact: 50, cost: 50, timeToValue: 50, risk: 50 }, notes: [] },
    ],
    criteria: [
      { id: 'impact', weight: 1, direction: 'higher_better' },
