export function analyzeDecision(input) {
  const options = input?.options || [];
  const criteria = input?.criteria || [];

  const ranked = options.map((opt) => {
    const scores = criteria.map((c) => {
      const v = Number(opt.metrics?.[c.id] ?? 0);
      return c.direction === 'lower_better' ? (100 - v) * c.weight : v * c.weight;
    });
    const score = scores.reduce((a, b) => a + b, 0);

    const pros = [];
    const cons = [];
    const unknowns = [];

    if ((opt.metrics?.cost ?? 50) < 40) pros.push('Lower projected cost');
    else cons.push('Higher projected cost');

    if ((opt.metrics?.timeToValue ?? 50) < 40) pros.push('Faster time-to-value');
    else cons.push('Slower expected rollout');

    if (opt.notes?.length === 0) unknowns.push('Limited qualitative evidence');

    const riskLevel = (opt.metrics?.risk ?? 50) > 65 ? 'high' : (opt.metrics?.risk ?? 50) > 35 ? 'medium' : 'low';

    return {
      id: opt.id,
      name: opt.name,
      score: Number(score.toFixed(2)),
      pros,
      cons,
      unknowns,
      riskLevel,
    };
  }).sort((a, b) => b.score - a.score);

  const riskMatrix = options.map((opt) => ({
    id: opt.id,
    name: opt.name,
    impact: Number(opt.metrics?.impact ?? 50),
    likelihood: Number(opt.metrics?.risk ?? 50),
    quadrant: quadrant(Number(opt.metrics?.impact ?? 50), Number(opt.metrics?.risk ?? 50)),
  }));

  const top = ranked[0];
  const actions = top
    ? [
        `Run 48-hour validation sprint for ${top.name}`,
        'Mitigate highest identified risk with owner + due date',
        'Prepare go/no-go review with measurable success metric',
      ]
    : [];

  return {
    ranked,
    riskMatrix,
    actionPlanTop3: actions,
  };
}

function quadrant(impact, likelihood) {
  if (impact >= 60 && likelihood >= 60) return 'critical';
  if (impact >= 60 && likelihood < 60) return 'watch';
  if (impact < 60 && likelihood >= 60) return 'mitigate';
  return 'low';
}

