    violations: list[str] = []
    for f in swift_files:
        txt = f.read_text(encoding="utf-8", errors="ignore")
        if "\t" in txt:
            violations.append(f"{f.name}: contains tab indentation")
        if any(len(line) > 160 for line in txt.splitlines()):
            violations.append(f"{f.name}: line length > 160")
    if violations:
        return False, "; ".join(violations[:6])
    return True, "Lint checks passed"


