import difflib
from dataclasses import dataclass
from pathlib import Path


@dataclass
class PatchStep:
    file: str
    action: str
    reason: str


def make_patch_plan(request: str, workspace: Path) -> list[PatchStep]:
    req = (request or "").lower()
    steps: list[PatchStep] = []

    if any(k in req for k in ["title", "heading", "header"]):
        steps.append(PatchStep(file="Features/HomeScreen.swift", action="update_title", reason="user requested title/header change"))
    if any(k in req for k in ["button", "cta"]):
        steps.append(PatchStep(file="engine/templates/component_kit.swift.tpl", action="tune_button", reason="user requested button-related change"))
    if not steps:
        steps.append(PatchStep(file="Features/HomeScreen.swift", action="append_note", reason="generic UI/content iteration"))

    return steps


def _replace_once(text: str, old: str, new: str) -> str:
    return text.replace(old, new, 1) if old in text else text + "\n" + new


def apply_patch_plan(workspace: Path, steps: list[PatchStep], request: str) -> tuple[list[str], list[dict]]:
    changed_files: list[str] = []
    diffs: list[dict] = []

    for step in steps:
        target = workspace / step.file
        if not target.exists():
            continue

        before = target.read_text(encoding="utf-8")
        after = before

        if step.action == "update_title":
            after = _replace_once(after, 'title: "Your Generated App"', 'title: "Your Updated App"')
        elif step.action == "tune_button":
            after = _replace_once(after, '.background(DSColor.brand)', '.background(DSColor.brand.opacity(0.95))')
        else:
            marker = f"// Iteration note: {request.strip()[:120]}"
            if marker not in after:
                after = after + "\n" + marker + "\n"

        if after != before:
            target.write_text(after, encoding="utf-8")
            changed_files.append(str(target))
            unified = "\n".join(
                difflib.unified_diff(
                    before.splitlines(),
                    after.splitlines(),
                    fromfile=f"a/{step.file}",
                    tofile=f"b/{step.file}",
                    lineterm="",
                )
            )
            diffs.append({"file": step.file, "action": step.action, "reason": step.reason, "diff": unified[:8000]})

    return changed_files, diffs

