from pathlib import Path


def _read_template(name: str) -> str:
    tpl = Path(__file__).parent / "templates" / name
    return tpl.read_text(encoding="utf-8")


def generate_ios_skeleton(root: Path) -> list[str]:
    root.mkdir(parents=True, exist_ok=True)

    app_entry = '''import SwiftUI

@main
struct GeneratedApp: App {
    var body: some Scene {
        WindowGroup {
            HomeScreen()
        }
    }
}
'''

    files = {
        "GeneratedApp.swift": app_entry,
        "DesignTokens.swift": _read_template("design_tokens.swift.tpl"),
        "ComponentKit.swift": _read_template("component_kit.swift.tpl"),
        "HomeScreen.swift": _read_template("sample_home.swift.tpl"),
    }

    written = []
    for name, content in files.items():
        p = root / name
        p.write_text(content, encoding="utf-8")
        written.append(str(p))
    return written

