import os
import re
import subprocess


def open_tunnel(url: str = "http://localhost:8787") -> str:
    bin_name = os.getenv("CLOUDFLARED_BIN", "cloudflared")
    proc = subprocess.Popen([bin_name, "tunnel", "--url", url], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    if not proc.stdout:
        return ""
    for _ in range(80):
        line = proc.stdout.readline()
        if not line:
            continue
        m = re.search(r"https://[a-z0-9\-]+\.trycloudflare\.com", line)
        if m:
            return m.group(0)
    return ""


